function finding(file, fix) {
  return {
    rule: rule.id,
    severity: rule.severity,
    file,
    line: null,
    what: `${file} is under a data tree but is not something a generator in this repo produces`,
    why: rule.why,
    fix,
    doc: rule.doc,
  };
}

