[Resource from github at repo://missingbulb/VascularColoring/sha/da146159fdd28c8d3827f43a9accb4445782406e/contents/.claudinite/local/packs/vascular-coloring/overlay-color-contrast.mjs] // The presentation overlay script — the one whose output the owner looks at.
// The 3-panel debug view in measure_vessels.py is deliberately NOT in scope: it
// dims the original and uses red for arteries, which is fine for a QA render and
// wrong for the presentation figure.
const PRESENTATION = 'analysis/annotate_overlays.py';

// An (r, g, b) or (r, g, b, a) literal — the only way a drawn colour is spelled
// in this script (PIL fill=/np.array colours).
const TUPLE = /\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*(?:,\s*\d{1,3}\s*)?\)/g;

// Red-dominant = bright red channel that clearly beats BOTH others. Magenta
// (255, 0, 255) and the yellow label colour (255, 235, 60) stay legal: they read
// against the red signal because blue resp. green carries them.
const MARGIN = 60;
const isRedDominant = (r, g, b) => r >= 128 && r - g >= MARGIN && r - b >= MARGIN;

const rule = {
  id: 'overlay-color-contrast',
  severity: 'blocking',
  description: 'Presentation overlay marks must not be red-dominant',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'the gP-CD31 signal being measured IS red — a red outline, arrow or ring vanishes on the very vessels it is supposed to mark',

  run(ctx) {
    const text = ctx.read(PRESENTATION);
    if (text === null) return [];
    const out = [];
    text.split('\n').forEach((line, i) => {
      // A comment or a docstring line describes a colour, it doesn't draw one.
      if (line.trim().startsWith('#')) return;
      for (const m of line.matchAll(TUPLE)) {
        const [r, g, b] = [m[1], m[2], m[3]].map(Number);
        if (!isRedDominant(r, g, b)) continue;
        out.push({
          rule: rule.id,
          severity: rule.severity,
          file: PRESENTATION,
          line: i + 1,
          what: `overlay colour (${r}, ${g}, ${b}) is red-dominant`,
          why: rule.why,
          fix: 'pick a colour that contrasts with the red channel — cyan for capillaries, green for arteries, magenta for junctions, yellow for labels (see the pack RULES.md)',
          doc: rule.doc,
        });
      }
    });
    return out;
  },
};

export default rule;

[Resource from github at repo://missingbulb/VascularColoring/sha/da146159fdd28c8d3827f43a9accb4445782406e/contents/.claudinite/local/packs/vascular-coloring/panel-scale-calibration.mjs] // Every panel in the working dataset is named VESSEL_<prefix>_... and lives under
// references/<paper-slug>/figures/panels/. The px -> um scale is measured from the scale bar
// the figure prints and tabulated as SCALEBAR_PX in the extraction script, keyed by panel-name
// prefix (longest match wins) so one figure can calibrate rows that differ in zoom.
//
// A panel may instead carry its scale DIRECTLY, in UMPP_DIRECT, when the source image's own
// metadata states um/px and no bar is involved — stronger evidence than a measured bar.
//
// A panel whose scale genuinely cannot be measured — the figure draws no bar — is not a
// violation, but it must SAY so: an entry in UNCALIBRATED, carrying the reason. The point of
// this rule is that no panel is uncalibrated by accident.
const PANEL = /^references\/[^/]+\/figures\/panels\/VESSEL_(.+)\.png$/i;
const MEASURE = 'analysis/measure_vessels.py';
const TABLE = /SCALEBAR_PX\s*=\s*\{([\s\S]*?)\}/;
const DIRECT = /UMPP_DIRECT\s*=\s*\{([\s\S]*?)\n\}/;
const DECLARED = /UNCALIBRATED\s*=\s*\{([\s\S]*?)\n\}/;

// The wang-2022 panels carry a channel suffix the calibration keys never include.
const stripSuffix = (s) => s.replace(/_gP-CD31_red$/, '');

const keysOf = (block) => (block ? [...block.matchAll(/['"]([^'"]+)['"]\s*:/g)].map((m) => m[1]) : []);

const rule = {
  id: 'panel-scale-calibration',
  severity: 'blocking',
  description: 'Every working panel is either scale-calibrated or declared uncalibrated',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'an uncalibrated figure does not fail — it silently reports "um n/a" and drops out of every length and density number, so a panel added without its bar measurement quietly shrinks the result set',

  run(ctx) {
    const text = ctx.read(MEASURE);
    if (text === null) return [];
    const lines = text.split('\n');
    const lineOf = (needle) => lines.findIndex((l) => l.includes(needle)) + 1 || null;
    const m = TABLE.exec(text);
    if (!m) {
      return [{
        rule: rule.id,
        severity: rule.severity,
        file: MEASURE,
        line: null,
        what: 'no SCALEBAR_PX table found',
        why: rule.why,
        fix: 'keep the per-prefix scale-bar widths in a SCALEBAR_PX = { ... } table in this file — it is the single calibration source annotate_overlays.py imports',
        doc: rule.doc,
      }];
    }
    const calibrated = keysOf(m[1]);
    const direct = keysOf(DIRECT.exec(text)?.[1]);
    const declared = keysOf(DECLARED.exec(text)?.[1]);
    const covers = (name) => [...calibrated, ...direct, ...declared].some((k) => name.startsWith(k));

    const panels = new Set();
    for (const f of ctx.tracked) {
      const hit = PANEL.exec(f);
      if (hit) panels.add(stripSuffix(hit[1]));
    }
    return [...panels].sort()
      .filter((name) => !covers(name))
      .map((name) => ({
        rule: rule.id,
        severity: rule.severity,
        file: MEASURE,
        line: lineOf('SCALEBAR_PX'),
        what: `VESSEL_${name} matches no SCALEBAR_PX, UMPP_DIRECT or UNCALIBRATED prefix`,
        why: rule.why,
        fix: `measure the scale bar printed on that panel's row and add a '<prefix>': <bar width in px> entry to SCALEBAR_PX (plus SCALEBAR_UM if the bar is not 50 um); or, if the source image states its own um/px, put it in UMPP_DIRECT with its provenance; or, if the figure draws no bar at all, add the prefix to UNCALIBRATED with the reason`,
        doc: rule.doc,
      }));
  },
};

export default rule;

[Resource from github at repo://missingbulb/VascularColoring/sha/da146159fdd28c8d3827f43a9accb4445782406e/contents/.claudinite/local/packs/vascular-coloring/render-outputs-gitignored.mjs] // Every render the pipeline produces is written into a directory the script
// creates for itself (measure_vessels.py --overlays -> analysis/overlays/,
// annotate_overlays.py -> analysis/annotated/). Those directories are gitignored,
// which is what makes "regenerate, never commit" hold under a `git add -A` or an
// agent staging a whole directory.
//
// Sibling of rendered-overlays-untracked, from the other side: that rule fires once
// a render is already tracked (the damage), this one keeps the ignore entry that
// stops it getting there. A newly added output directory is the real gap — it is
// gitignored only if someone remembers, and nothing said so until now.
//
// Parse rather than grep: an output directory is one the script actually creates
// (`os.makedirs(...)`), resolved through the script's own `HERE` constant, with
// comments and string literals handled — a path mentioned in a docstring is not a
// directory anything writes to.
const SHARED = '.claudinite/shared/';        // read-only mounted canon
const HERE_DEF = /^\s*HERE\s*=\s*os\.path\.dirname\(\s*os\.path\.abspath\(\s*__file__\s*\)\s*\)/m;
// NAME = os.path.join(HERE, 'annotated')  /  os.path.join(HERE, 'a', 'b')
const JOIN = /(?:^|[^\w.])([A-Za-z_]\w*)\s*=\s*os\.path\.join\(\s*HERE\s*,\s*((?:'[^']*'|"[^"]*")(?:\s*,\s*(?:'[^']*'|"[^"]*"))*)\s*\)/g;
const MAKEDIRS = /os\.makedirs\(\s*([A-Za-z_]\w*)\b/g;
const PARTS = /'([^']*)'|"([^"]*)"/g;

// Comments stripped, string literals kept: the joined path segments ARE literals,
// so this only removes `#` runs that are not inside a string.
function uncomment(text) {
  return text.split('\n').map((line) => {
    let quote = null;
    for (let i = 0; i < line.length; i += 1) {
      const c = line[i];
      if (quote) {
        if (c === '\\') i += 1;
        else if (c === quote) quote = null;
      } else if (c === '"' || c === "'") quote = c;
      else if (c === '#') return line.slice(0, i);
    }
    return line;
  }).join('\n');
}

const dirOf = (file) => (file.includes('/') ? file.slice(0, file.lastIndexOf('/')) : '');
const joinPath = (...ps) => ps.filter(Boolean).join('/');

// The directories a script creates under its own location, as repo-relative paths
// with the line of the makedirs call. Empty unless HERE is the script's own dir —
// an unrecognised layout is left alone rather than guessed at.
function createdDirs(file, source) {
  const text = uncomment(source);
  if (!HERE_DEF.test(text)) return [];
  const here = dirOf(file);
  const consts = new Map();
  for (const m of text.matchAll(JOIN)) {
    const segs = [...m[2].matchAll(PARTS)].map((p) => p[1] ?? p[2]);
    if (segs.some((s) => s === '..' || s === '')) continue;   // escapes the script's dir
    consts.set(m[1], joinPath(here, ...segs));
  }
  const out = new Map();
  for (const m of text.matchAll(MAKEDIRS)) {
    const path = consts.get(m[1]);
    if (!path || out.has(path)) continue;
    out.set(path, { path, name: m[1], line: text.slice(0, m.index).split('\n').length });
  }
  return [...out.values()];
}

// The ignore patterns that can cover `dir`: git reads a .gitignore per directory,
// so every ancestor of `dir` gets one — root first, deepest last, which is also
// git's precedence order (the last matching pattern wins). A .gitignore *inside*
// `dir` is excluded: it cannot cause its own directory to be ignored. Each entry
// is returned as { path, negated, anchored }, normalised to a repo-relative path
// or a bare name git matches at any depth below that .gitignore's directory.
function patterns(ctx, dir) {
  const segs = dir.split('/').slice(0, -1);
  const bases = ['', ...segs.map((_, i) => segs.slice(0, i + 1).join('/'))];
  const out = [];
  for (const base of new Set(bases)) {
    const text = ctx.read(joinPath(base, '.gitignore'));
    if (text === null) continue;
    for (const raw of text.split('\n')) {
      const line = raw.trim();
      if (!line || line.startsWith('#')) continue;
      const negated = line.startsWith('!');
      const body = (negated ? line.slice(1) : line).replace(/\/+$/, '');
      if (!body) continue;
      const anchored = body.includes('/');
      out.push({ base, negated, anchored, path: anchored ? joinPath(base, body.replace(/^\/+/, '')) : body });
    }
  }
  return out;
}

const covers = (p, dir) => (p.anchored
  ? dir === p.path || dir.startsWith(`${p.path}/`)
  // A bare name matches any path component at or below the .gitignore's directory.
  : (dir === p.base || dir.startsWith(`${p.base}/`) || p.base === '')
    && dir.split('/').includes(p.path));

// Last matching pattern wins in git, negation included.
function ignored(ctx, dir) {
  const hits = patterns(ctx, dir).filter((p) => covers(p, dir));
  return hits.length > 0 && !hits[hits.length - 1].negated;
}

const rule = {
  id: 'render-outputs-gitignored',
  severity: 'blocking',
  description: 'Every directory a script renders into is gitignored',
  doc: '.claudinite/local/packs/vascular-coloring/skills/vessel-overlay-review/SKILL.md',
  why: 'overlay renders are regenerated from the scripts, not data — an output directory that is not ignored gets swept into the repo by the first `git add -A` after a run, and from then on a stale PNG is what reviewers see instead of what the current script draws',

  run(ctx) {
    const out = [];
    for (const file of ctx.tracked) {
      if (!file.endsWith('.py') || file.startsWith(SHARED)) continue;
      const text = ctx.read(file);
      if (text === null) continue;
      for (const dir of createdDirs(file, text)) {
        if (ignored(ctx, dir.path)) continue;
        out.push({
          rule: rule.id,
          severity: rule.severity,
          file,
          line: dir.line,
          what: `${file} renders into ${dir.path}/, which no .gitignore entry covers`,
          why: rule.why,
          fix: `add \`/${dir.path}/\` to .gitignore (with a comment naming the command that regenerates it, as the existing render entries do); if ${dir.path}/ holds real data or agreed ground truth rather than renders, it belongs under references/ instead`,
          doc: rule.doc,
        });
      }
    }
    return out;
  },
};

export default rule;

[Resource from github at repo://missingbulb/VascularColoring/sha/da146159fdd28c8d3827f43a9accb4445782406e/contents/.claudinite/local/packs/vascular-coloring/rendered-overlays-untracked.mjs] // Rendered output lives under analysis/ (measure_vessels.py --overlays writes
// analysis/overlays/, annotate_overlays.py writes analysis/annotated/); both are
// gitignored and regenerated. The real source images live under references/.
const RENDER_ROOT = 'analysis/';
const IMAGE = /\.(png|jpe?g|tiff?|gif|bmp|webp)$/i;

const rule = {
  id: 'rendered-overlays-untracked',
  severity: 'blocking',
  description: 'No rendered overlay image is committed under analysis/',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'an overlay PNG is a regenerable render, not data — committing one freezes a snapshot that silently stops matching the scripts, and the owner\'s rule is that only real data or an agreed ground-truth image gets committed',

  run(ctx) {
    return ctx.tracked
      .filter((f) => f.startsWith(RENDER_ROOT) && IMAGE.test(f))
      .map((f) => ({
        rule: rule.id,
        severity: rule.severity,
        file: f,
        line: null,
        what: `${f} is a tracked image under ${RENDER_ROOT}`,
        why: rule.why,
        fix: 'untrack it (git rm --cached) and regenerate with python3 analysis/measure_vessels.py --overlays or python3 analysis/annotate_overlays.py — commit the script and the numeric results instead; if the image really is data or agreed ground truth, put it under references/',
        doc: rule.doc,
      }));
  },
};

export default rule;

[Resource from github at repo://missingbulb/VascularColoring/sha/da146159fdd28c8d3827f43a9accb4445782406e/contents/.claudinite/local/packs/vascular-coloring/scale-numbers-match-calibration.mjs] // The px -> um scale of every figure is derived from ONE source: UM_PER_BAR /
// SCALEBAR_PX in the extraction script (the measured 50 um bar widths). The docs
// quote those numbers in three places (the pack RULES, the working guide, the
// results calibration table) — this check keeps the copies honest.
//
// Detection is column/label-scoped, never a bare grep for decimals: a claim is
// read only from an inline `figN = <value>` in a passage that says "um/px", or
// from a markdown table's own um/px and bar-width COLUMNS, and only when the
// figure cell names a figure rather than a panel. That is what keeps the per-panel
// results table (fig1_C1_healthy | 2145 | 23.6 | ...) out of scope.
const MEASURE = 'analysis/measure_vessels.py';
const SKIP = '.claudinite/shared/';                 // read-only mounted canon
const UM_PER_BAR = /UM_PER_BAR\s*=\s*([\d.]+)/;
const TABLE = /SCALEBAR_PX\s*=\s*\{([^}]*)\}/;

const MU = '[µμu]';                       // micro sign / greek mu / plain "u"
const MU_LABEL = 'µm/px';
const UMPP = new RegExp(`${MU}m\\s*/\\s*px`, 'i');  // the unit that marks a scale claim
// "fig1 = 0.820", "fig4/5/6 = 0.658", "fig4 / fig5 = 0.658"
const INLINE = /\bfig(\d+(?:\s*\/\s*(?:fig)?\d+)*)\s*=\s*\*{0,2}[~≈]?\s*(\d+(?:\.\d+)?)/g;
// a table cell that is just a number, optionally in px and/or bold: "61 px", "**0.820**"
const NUM_CELL = /^\*{0,2}[~≈]?\s*(\d+(?:\.\d+)?)\s*(?:px)?\s*\*{0,2}$/;

// The figures a label names — "fig1", "fig4/5/6", "fig4 / fig5". Anything that is
// not a bare figure number is dropped, so a panel-level label ("fig1_C1_healthy",
// "fig1 crop A2") names no figure and carries no claim.
const figsOf = (labels) => labels
  .split(/[/,]/)
  .map((p) => p.trim().replace(/^fig/i, ''))
  .filter((p) => /^\d+$/.test(p))
  .map((p) => `fig${p}`);

// A quoted value agrees if it matches the true value rounded to the precision the
// doc chose to quote it at (0.820, 0.82 and 0.8197 all describe 50/61).
const agrees = (quoted, truth) => {
  const dp = (quoted.split('.')[1] || '').length;
  return Number(quoted) === Number(truth.toFixed(dp));
};

const cells = (line) => line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((c) => c.trim());

// Blank-line-separated blocks, with the 1-based line each block starts on.
const blocks = (text) => {
  const out = [];
  let cur = null;
  text.split('\n').forEach((line, i) => {
    if (line.trim() === '') { cur = null; return; }
    if (!cur) { cur = { start: i + 1, lines: [] }; out.push(cur); }
    cur.lines.push(line);
  });
  return out;
};

const rule = {
  id: 'scale-numbers-match-calibration',
  severity: 'blocking',
  description: 'Scale numbers quoted in the docs match the SCALEBAR_PX calibration',
  doc: '.claudinite/local/packs/vascular-coloring/RULES.md',
  why: 'the um/px per figure is derived from one measured table (UM_PER_BAR / SCALEBAR_PX); a doc that quotes a stale copy does not fail loudly — it silently re-labels every length and density number in that document with the wrong scale',

  run(ctx) {
    const src = ctx.read(MEASURE);
    if (src === null) return [];
    const perBar = UM_PER_BAR.exec(src);
    const table = TABLE.exec(src);
    // No calibration source to compare against: panel-scale-calibration owns that.
    if (!perBar || !table) return [];
    const bar = new Map(
      [...table[1].matchAll(/['"]([^'"]+)['"]\s*:\s*(\d+(?:\.\d+)?)/g)].map((m) => [m[1], Number(m[2])]),
    );
    const um = Number(perBar[1]);
    const truth = (fig, kind) => {
      const px = bar.get(fig);
      if (px === undefined) return null;               // uncalibrated figure -> not this rule
      return kind === 'bar' ? px : um / px;
    };

    const out = [];
    const flag = (file, line, fig, kind, quoted, expected) => out.push({
      rule: rule.id,
      severity: rule.severity,
      file,
      line,
      what: kind === 'bar'
        ? `${fig}'s scale bar is quoted as ${quoted} px but SCALEBAR_PX says ${expected}`
        : `${fig}'s scale is quoted as ${quoted} ${MU_LABEL} but SCALEBAR_PX gives ${expected}`,
      why: rule.why,
      fix: kind === 'bar'
        ? `quote ${fig}'s bar as ${expected} px, or fix SCALEBAR_PX in ${MEASURE} if the measurement changed — the table is the single source`
        : `quote ${expected} ${MU_LABEL} for ${fig} (UM_PER_BAR / SCALEBAR_PX['${fig}']), or fix the table in ${MEASURE} if the measurement changed`,
      doc: rule.doc,
    });

    for (const file of ctx.tracked) {
      if (!file.endsWith('.md') || file.startsWith(SKIP)) continue;
      const text = ctx.read(file);
      if (text === null) continue;

      for (const blk of blocks(text)) {
        const body = blk.lines.join('\n');
        if (!UMPP.test(body)) continue;               // no scale claim in this passage

        // --- inline prose claims: "fig1 = 0.820" ---------------------------
        blk.lines.forEach((line, i) => {
          if (line.trim().startsWith('|')) return;    // table rows handled below
          for (const m of line.matchAll(INLINE)) {
            for (const fig of figsOf(m[1])) {
              const t = truth(fig, 'umpp');
              if (t === null) continue;
              if (!agrees(m[2], t)) flag(file, blk.start + i, fig, 'umpp', m[2], t.toFixed(3));
            }
          }
        });

        // --- table columns: a um/px column and/or a bar-width column -------
        const rows = blk.lines.map((l, i) => ({ line: blk.start + i, raw: l }))
          .filter((r) => r.raw.trim().startsWith('|'));
        if (rows.length < 3) continue;
        const head = cells(rows[0].raw);
        const figCol = head.findIndex((c) => /fig/i.test(c));
        const umppCol = head.findIndex((c) => UMPP.test(c));
        const barCol = head.findIndex((c, i) => i !== umppCol && /bar/i.test(c) && /px|m\b/i.test(c));
        if (figCol < 0 || (umppCol < 0 && barCol < 0)) continue;
        for (const row of rows.slice(2)) {            // skip header + |---| separator
          const cs = cells(row.raw);
          const label = (cs[figCol] || '').replace(/\*/g, '').trim();
          for (const [col, kind] of [[umppCol, 'umpp'], [barCol, 'bar']]) {
            if (col < 0) continue;
            const hit = NUM_CELL.exec(cs[col] || '');
            if (!hit) continue;
            for (const fig of figsOf(label)) {
              const t = truth(fig, kind);
              if (t === null) continue;
              if (!agrees(hit[1], t)) {
                flag(file, row.line, fig, kind, hit[1], kind === 'bar' ? String(t) : t.toFixed(3));
              }
            }
          }
        }
      }
    }
    return out;
  },
};

export default rule;

